var e={kind:`dp`,caption:`nums = [2, 3, -2, -4, 0, 3]（求乘积最大的连续子数组，下面两行是"以这一格结尾"的最大积 / 最小积）`,corner:``,rowLabels:[`nums`,`最大积`,`最小积`],colLabels:[`i = 0`,`i = 1`,`i = 2`,`i = 3`,`i = 4`,`i = 5`],frames:[{step:0,note:`三个变量都从 nums[0] = 2 起步：以第 0 个元素结尾的子数组只能是它自己，最大积和最小积都只有这一个候选。注意不能拿 0 或 1 当初值 —— 数组要是只有一个负数，用 0 起步就会错误地返回 0。`,values:{"0,0":`2`,"0,1":`3`,"0,2":`-2`,"0,3":`-4`,"0,4":`0`,"0,5":`3`,"1,0":`2`,"2,0":`2`},focus:{r:1,c:0},deps:[{r:0,c:0}],state:{},marks:{cur_max:{r:1,c:0},cur_min:{r:2,c:0}},band:null,aux:null,out:`ans = 2`},{step:1,note:`轮到 x = nums[1] = 3。它不是负数，乘上去不会翻转大小关系，可以直接套公式。`,values:{"0,0":`2`,"0,1":`3`,"0,2":`-2`,"0,3":`-4`,"0,4":`0`,"0,5":`3`,"1,0":`2`,"2,0":`2`},focus:{r:0,c:1},deps:[],state:{},marks:{cur_max:{r:1,c:0},cur_min:{r:2,c:0}},band:null,aux:null,out:`ans = 2`},{step:3,note:`cur_max = max(x, cur_max × x) = max(3, 2 × 3 = 6) = 6。两个候选就是"从 3 自己重新开一段"和"把前面那段接上"，谁大要谁。这次是把前面接上更划算。`,values:{"0,0":`2`,"0,1":`3`,"0,2":`-2`,"0,3":`-4`,"0,4":`0`,"0,5":`3`,"1,0":`2`,"2,0":`2`,"1,1":`6`},focus:{r:1,c:1},deps:[{r:0,c:1},{r:1,c:0}],state:{},marks:{cur_max:{r:1,c:1},cur_min:{r:2,c:0}},band:null,aux:null,out:`ans = 2`},{step:4,note:`cur_min = min(x, cur_min × x) = min(3, 2 × 3 = 6) = 3。这一步的最小积是 3，不是负数，眼下派不上任何用场 —— 但它必须一路跟着算，底牌只能提前攒，等真遇到负数时是补不出来的。`,values:{"0,0":`2`,"0,1":`3`,"0,2":`-2`,"0,3":`-4`,"0,4":`0`,"0,5":`3`,"1,0":`2`,"2,0":`2`,"1,1":`6`,"2,1":`3`},focus:{r:2,c:1},deps:[{r:0,c:1},{r:2,c:0}],state:{},marks:{cur_max:{r:1,c:1},cur_min:{r:2,c:1}},band:null,aux:null,out:`ans = 2`},{step:5,note:`ans = max(2, 6) = 6，纪录被刷新了，冠军现在是以 i = 1 结尾的那一段。`,values:{"0,0":`2`,"0,1":`3`,"0,2":`-2`,"0,3":`-4`,"0,4":`0`,"0,5":`3`,"1,0":`2`,"2,0":`2`,"1,1":`6`,"2,1":`3`},focus:null,deps:[],state:{"1,1":`hit`},marks:{cur_max:{r:1,c:1},cur_min:{r:2,c:1}},band:null,aux:null,out:`ans = 6`},{step:1,note:`轮到 x = nums[2] = -2。它是负数 —— 乘上去会把大小关系整个翻过来，所以先别急着套公式。`,values:{"0,0":`2`,"0,1":`3`,"0,2":`-2`,"0,3":`-4`,"0,4":`0`,"0,5":`3`,"1,0":`2`,"2,0":`2`,"1,1":`6`,"2,1":`3`},focus:{r:0,c:2},deps:[],state:{},marks:{cur_max:{r:1,c:1},cur_min:{r:2,c:1}},band:null,aux:null,out:`ans = 6`},{step:2,note:`x = -2 是负数，先交换：cur_max 从 6 变成 3，cur_min 从 3 变成 6。看两个标记跨行换了位置 —— 乘一个负数后，原来最小的那个才会变成最大的，交换之后下面照常取 max / min 就仍然成立。交换必须在更新之前，先算完 cur_max 再拿新值去算 cur_min，两个状态就串了。`,values:{"0,0":`2`,"0,1":`3`,"0,2":`-2`,"0,3":`-4`,"0,4":`0`,"0,5":`3`,"1,0":`2`,"2,0":`2`,"1,1":`6`,"2,1":`3`},focus:null,deps:[],state:{},marks:{cur_max:{r:2,c:1},cur_min:{r:1,c:1}},band:null,aux:null,out:`ans = 6`},{step:3,note:`cur_max = max(x, cur_max × x) = max(-2, 3 × -2 = -6) = -2。两个候选就是"从 -2 自己重新开一段"和"把前面那段接上"，谁大要谁。这次是重新开一段 —— 把前面接上只有 -6，反而更小。`,values:{"0,0":`2`,"0,1":`3`,"0,2":`-2`,"0,3":`-4`,"0,4":`0`,"0,5":`3`,"1,0":`2`,"2,0":`2`,"1,1":`6`,"2,1":`3`,"1,2":`-2`},focus:{r:1,c:2},deps:[{r:0,c:2},{r:2,c:1}],state:{},marks:{cur_max:{r:1,c:2},cur_min:{r:1,c:1}},band:null,aux:null,out:`ans = 6`},{step:4,note:`cur_min = min(x, cur_min × x) = min(-2, 6 × -2 = -12) = -12。-12 这种负数本身当然不是答案，留着它是当底牌：再撞上一个负数，一乘就翻身成很大的正数。而且下一步就兑现：nums[3] = -4 又是负数，-12 × -4 = 48，这张底牌当场翻成最大积，还会把 ans 从 6 顶到 48。`,values:{"0,0":`2`,"0,1":`3`,"0,2":`-2`,"0,3":`-4`,"0,4":`0`,"0,5":`3`,"1,0":`2`,"2,0":`2`,"1,1":`6`,"2,1":`3`,"1,2":`-2`,"2,2":`-12`},focus:{r:2,c:2},deps:[{r:0,c:2},{r:1,c:1}],state:{},marks:{cur_max:{r:1,c:2},cur_min:{r:2,c:2}},band:null,aux:null,out:`ans = 6`},{step:5,note:`ans = max(6, -2) = 6，这一步没能刷新纪录，但仍要比一次：最优子数组不一定结尾在最后一个元素上，只在循环结束后看 cur_max 是会漏答案的。`,values:{"0,0":`2`,"0,1":`3`,"0,2":`-2`,"0,3":`-4`,"0,4":`0`,"0,5":`3`,"1,0":`2`,"2,0":`2`,"1,1":`6`,"2,1":`3`,"1,2":`-2`,"2,2":`-12`},focus:null,deps:[],state:{"1,1":`hit`},marks:{cur_max:{r:1,c:2},cur_min:{r:2,c:2}},band:null,aux:null,out:`ans = 6`},{step:1,note:`轮到 x = nums[3] = -4。它是负数 —— 乘上去会把大小关系整个翻过来，所以先别急着套公式。`,values:{"0,0":`2`,"0,1":`3`,"0,2":`-2`,"0,3":`-4`,"0,4":`0`,"0,5":`3`,"1,0":`2`,"2,0":`2`,"1,1":`6`,"2,1":`3`,"1,2":`-2`,"2,2":`-12`},focus:{r:0,c:3},deps:[],state:{},marks:{cur_max:{r:1,c:2},cur_min:{r:2,c:2}},band:null,aux:null,out:`ans = 6`},{step:2,note:`x = -4 是负数，先交换：cur_max 从 -2 变成 -12，cur_min 从 -12 变成 -2。看两个标记跨行换了位置 —— 乘一个负数后，原来最小的那个才会变成最大的，交换之后下面照常取 max / min 就仍然成立。交换必须在更新之前，先算完 cur_max 再拿新值去算 cur_min，两个状态就串了。`,values:{"0,0":`2`,"0,1":`3`,"0,2":`-2`,"0,3":`-4`,"0,4":`0`,"0,5":`3`,"1,0":`2`,"2,0":`2`,"1,1":`6`,"2,1":`3`,"1,2":`-2`,"2,2":`-12`},focus:null,deps:[],state:{},marks:{cur_max:{r:2,c:2},cur_min:{r:1,c:2}},band:null,aux:null,out:`ans = 6`},{step:3,note:`cur_max = max(x, cur_max × x) = max(-4, -12 × -4 = 48) = 48。两个候选就是"从 -4 自己重新开一段"和"把前面那段接上"，谁大要谁。这次是把前面接上更划算。`,values:{"0,0":`2`,"0,1":`3`,"0,2":`-2`,"0,3":`-4`,"0,4":`0`,"0,5":`3`,"1,0":`2`,"2,0":`2`,"1,1":`6`,"2,1":`3`,"1,2":`-2`,"2,2":`-12`,"1,3":`48`},focus:{r:1,c:3},deps:[{r:0,c:3},{r:2,c:2}],state:{},marks:{cur_max:{r:1,c:3},cur_min:{r:1,c:2}},band:null,aux:null,out:`ans = 6`},{step:4,note:`cur_min = min(x, cur_min × x) = min(-4, -2 × -4 = 8) = -4。-4 这种负数本身当然不是答案，留着它是当底牌：再撞上一个负数，一乘就翻身成很大的正数。`,values:{"0,0":`2`,"0,1":`3`,"0,2":`-2`,"0,3":`-4`,"0,4":`0`,"0,5":`3`,"1,0":`2`,"2,0":`2`,"1,1":`6`,"2,1":`3`,"1,2":`-2`,"2,2":`-12`,"1,3":`48`,"2,3":`-4`},focus:{r:2,c:3},deps:[{r:0,c:3},{r:1,c:2}],state:{},marks:{cur_max:{r:1,c:3},cur_min:{r:2,c:3}},band:null,aux:null,out:`ans = 6`},{step:5,note:`ans = max(6, 48) = 48，纪录被刷新了，冠军现在是以 i = 3 结尾的那一段。`,values:{"0,0":`2`,"0,1":`3`,"0,2":`-2`,"0,3":`-4`,"0,4":`0`,"0,5":`3`,"1,0":`2`,"2,0":`2`,"1,1":`6`,"2,1":`3`,"1,2":`-2`,"2,2":`-12`,"1,3":`48`,"2,3":`-4`},focus:null,deps:[],state:{"1,3":`hit`},marks:{cur_max:{r:1,c:3},cur_min:{r:2,c:3}},band:null,aux:null,out:`ans = 48`},{step:1,note:`轮到 x = nums[4] = 0。它不是负数，乘上去不会翻转大小关系，可以直接套公式。`,values:{"0,0":`2`,"0,1":`3`,"0,2":`-2`,"0,3":`-4`,"0,4":`0`,"0,5":`3`,"1,0":`2`,"2,0":`2`,"1,1":`6`,"2,1":`3`,"1,2":`-2`,"2,2":`-12`,"1,3":`48`,"2,3":`-4`},focus:{r:0,c:4},deps:[],state:{},marks:{cur_max:{r:1,c:3},cur_min:{r:2,c:3}},band:null,aux:null,out:`ans = 48`},{step:3,note:`cur_max = max(x, cur_max × x) = max(0, 48 × 0 = 0) = 0。两个候选就是"从 0 自己重新开一段"和"把前面那段接上"，谁大要谁。两个候选一样是 0：前面攒的乘积被这个 0 清光了，取 max 之后自然等于"从这里重新起步"，所以含 0 的数据根本不用特判。`,values:{"0,0":`2`,"0,1":`3`,"0,2":`-2`,"0,3":`-4`,"0,4":`0`,"0,5":`3`,"1,0":`2`,"2,0":`2`,"1,1":`6`,"2,1":`3`,"1,2":`-2`,"2,2":`-12`,"1,3":`48`,"2,3":`-4`,"1,4":`0`},focus:{r:1,c:4},deps:[{r:0,c:4},{r:1,c:3}],state:{},marks:{cur_max:{r:1,c:4},cur_min:{r:2,c:3}},band:null,aux:null,out:`ans = 48`},{step:4,note:`cur_min = min(x, cur_min × x) = min(0, -4 × 0 = 0) = 0。这一步的最小积是 0，不是负数，眼下派不上任何用场 —— 但它必须一路跟着算，底牌只能提前攒，等真遇到负数时是补不出来的。`,values:{"0,0":`2`,"0,1":`3`,"0,2":`-2`,"0,3":`-4`,"0,4":`0`,"0,5":`3`,"1,0":`2`,"2,0":`2`,"1,1":`6`,"2,1":`3`,"1,2":`-2`,"2,2":`-12`,"1,3":`48`,"2,3":`-4`,"1,4":`0`,"2,4":`0`},focus:{r:2,c:4},deps:[{r:0,c:4},{r:2,c:3}],state:{},marks:{cur_max:{r:1,c:4},cur_min:{r:2,c:4}},band:null,aux:null,out:`ans = 48`},{step:5,note:`ans = max(48, 0) = 48，这一步没能刷新纪录，但仍要比一次：最优子数组不一定结尾在最后一个元素上，只在循环结束后看 cur_max 是会漏答案的。`,values:{"0,0":`2`,"0,1":`3`,"0,2":`-2`,"0,3":`-4`,"0,4":`0`,"0,5":`3`,"1,0":`2`,"2,0":`2`,"1,1":`6`,"2,1":`3`,"1,2":`-2`,"2,2":`-12`,"1,3":`48`,"2,3":`-4`,"1,4":`0`,"2,4":`0`},focus:null,deps:[],state:{"1,3":`hit`},marks:{cur_max:{r:1,c:4},cur_min:{r:2,c:4}},band:null,aux:null,out:`ans = 48`},{step:1,note:`轮到 x = nums[5] = 3。它不是负数，乘上去不会翻转大小关系，可以直接套公式。`,values:{"0,0":`2`,"0,1":`3`,"0,2":`-2`,"0,3":`-4`,"0,4":`0`,"0,5":`3`,"1,0":`2`,"2,0":`2`,"1,1":`6`,"2,1":`3`,"1,2":`-2`,"2,2":`-12`,"1,3":`48`,"2,3":`-4`,"1,4":`0`,"2,4":`0`},focus:{r:0,c:5},deps:[],state:{},marks:{cur_max:{r:1,c:4},cur_min:{r:2,c:4}},band:null,aux:null,out:`ans = 48`},{step:3,note:`cur_max = max(x, cur_max × x) = max(3, 0 × 3 = 0) = 3。两个候选就是"从 3 自己重新开一段"和"把前面那段接上"，谁大要谁。这次是重新开一段 —— 把前面接上只有 0，反而更小。`,values:{"0,0":`2`,"0,1":`3`,"0,2":`-2`,"0,3":`-4`,"0,4":`0`,"0,5":`3`,"1,0":`2`,"2,0":`2`,"1,1":`6`,"2,1":`3`,"1,2":`-2`,"2,2":`-12`,"1,3":`48`,"2,3":`-4`,"1,4":`0`,"2,4":`0`,"1,5":`3`},focus:{r:1,c:5},deps:[{r:0,c:5},{r:1,c:4}],state:{},marks:{cur_max:{r:1,c:5},cur_min:{r:2,c:4}},band:null,aux:null,out:`ans = 48`},{step:4,note:`cur_min = min(x, cur_min × x) = min(3, 0 × 3 = 0) = 0。这一步的最小积是 0，不是负数，眼下派不上任何用场 —— 但它必须一路跟着算，底牌只能提前攒，等真遇到负数时是补不出来的。`,values:{"0,0":`2`,"0,1":`3`,"0,2":`-2`,"0,3":`-4`,"0,4":`0`,"0,5":`3`,"1,0":`2`,"2,0":`2`,"1,1":`6`,"2,1":`3`,"1,2":`-2`,"2,2":`-12`,"1,3":`48`,"2,3":`-4`,"1,4":`0`,"2,4":`0`,"1,5":`3`,"2,5":`0`},focus:{r:2,c:5},deps:[{r:0,c:5},{r:2,c:4}],state:{},marks:{cur_max:{r:1,c:5},cur_min:{r:2,c:5}},band:null,aux:null,out:`ans = 48`},{step:5,note:`ans = max(48, 3) = 48，这一步没能刷新纪录，但仍要比一次：最优子数组不一定结尾在最后一个元素上，只在循环结束后看 cur_max 是会漏答案的。`,values:{"0,0":`2`,"0,1":`3`,"0,2":`-2`,"0,3":`-4`,"0,4":`0`,"0,5":`3`,"1,0":`2`,"2,0":`2`,"1,1":`6`,"2,1":`3`,"1,2":`-2`,"2,2":`-12`,"1,3":`48`,"2,3":`-4`,"1,4":`0`,"2,4":`0`,"1,5":`3`,"2,5":`0`},focus:null,deps:[],state:{"1,3":`hit`},marks:{cur_max:{r:1,c:5},cur_min:{r:2,c:5}},band:null,aux:null,out:`ans = 48`},{step:5,note:`扫完一遍，返回 ans = 48，冠军是以 i = 3 结尾的那一段。补一句：这一段具体从哪儿开始，是我把表倒着读一遍才认出来的 —— nums[0..3]，也就是 2 × 3 × -2 × -4 = 48；参考解到上一帧就已经返回了，它只要那个最大值，不需要做这一步回溯。全程三个变量、一趟扫描，上面整张表都是画给你看的，代码从头到尾只握着标记指着的那两格。`,values:{"0,0":`2`,"0,1":`3`,"0,2":`-2`,"0,3":`-4`,"0,4":`0`,"0,5":`3`,"1,0":`2`,"2,0":`2`,"1,1":`6`,"2,1":`3`,"1,2":`-2`,"2,2":`-12`,"1,3":`48`,"2,3":`-4`,"1,4":`0`,"2,4":`0`,"1,5":`3`,"2,5":`0`},focus:null,deps:[],state:{"1,3":`hit`},marks:{cur_max:{r:1,c:5},cur_min:{r:2,c:5}},band:null,aux:null,out:`返回 48`}]};export{e as default};